76	impl WebWindow {
77	    pub(crate) fn prepare_canvas(
78	        browser_window: &web_sys::Window,
79	    ) -> anyhow::Result<web_sys::HtmlCanvasElement> {
80	        let document = browser_window
81	            .document()
82	            .ok_or_else(|| anyhow::anyhow!("No `document` found on window"))?;
83	        let canvas: web_sys::HtmlCanvasElement = document
84	            .create_element("canvas")
85	            .map_err(|error| anyhow::anyhow!("Failed to create canvas element: {error:?}"))?
86	            .dyn_into()
87	            .map_err(|error| anyhow::anyhow!("Created element is not a canvas: {error:?}"))?;
88	        canvas.set_tab_index(-1);
89	
90	        let style = canvas.style();
91	        for (property, value) in [
92	            ("width", "100%"),
93	            ("height", "100%"),
94	            ("display", "block"),
95	            ("outline", "none"),
96	            ("touch-action", "none"),
97	        ] {
98	            style.set_property(property, value).map_err(|error| {
99	                anyhow::anyhow!("Failed to set canvas {property} style: {error:?}")
100	            })?;
101	        }
102	
103	        let body = document
104	            .body()
105	            .ok_or_else(|| anyhow::anyhow!("No `body` found on document"))?;
106	        body.append_child(&canvas)
107	            .map_err(|error| anyhow::anyhow!("Failed to append canvas to body: {error:?}"))?;
108	        Ok(canvas)
109	    }
