111	    #[allow(clippy::too_many_arguments)]
112	    pub(crate) fn new(
113	        _handle: AnyWindowHandle,
114	        _params: WindowParams,
115	        context: &WgpuContext,
116	        canvas: web_sys::HtmlCanvasElement,
117	        surface: wgpu::Surface<'static>,
118	        browser_window: web_sys::Window,
119	        lifecycle: Rc<Cell<WebWindowLifecycle>>,
120	        active_window: Rc<RefCell<Option<AnyWindowHandle>>>,
121	    ) -> anyhow::Result<Self> {
122	        let document = browser_window
123	            .document()
124	            .ok_or_else(|| anyhow::anyhow!("No `document` found on window"))?;
125	        let body = document
126	            .body()
127	            .ok_or_else(|| anyhow::anyhow!("No `body` found on document"))?;
128	        let dpr = browser_window.device_pixel_ratio() as f32;
129	        let max_texture_dimension = context.device.limits().max_texture_dimension_2d;
130	        let has_device_pixel_support = check_device_pixel_support();
131	        let renderer_config = WgpuSurfaceConfig {
132	            size: Size {
133	                width: DevicePixels(0),
134	                height: DevicePixels(0),
135	            },
136	            transparent: false,
137	            preferred_present_mode: None,
138	        };
139	        let renderer = WgpuRenderer::new_from_surface(context, surface, renderer_config)?;
140	
141	        let input_element: web_sys::HtmlInputElement = document
142	            .create_element("input")
143	            .map_err(|e| anyhow::anyhow!("Failed to create input element: {e:?}"))?
144	            .dyn_into()
145	            .map_err(|e| anyhow::anyhow!("Created element is not an input: {e:?}"))?;
146	        let input_style = input_element.style();
147	        input_style.set_property("position", "fixed").ok();
148	        input_style.set_property("top", "0").ok();
149	        input_style.set_property("left", "0").ok();
150	        input_style.set_property("width", "1px").ok();
151	        input_style.set_property("height", "1px").ok();
152	        input_style.set_property("opacity", "0").ok();
153	        body.append_child(&input_element)
154	            .map_err(|e| anyhow::anyhow!("Failed to append input to body: {e:?}"))?;
155	        input_element.focus().ok();
156	
157	        let display: Rc<dyn PlatformDisplay> = Rc::new(WebDisplay::new(browser_window.clone()));
158	
159	        let initial_bounds = Bounds {
160	            origin: Point::default(),
161	            size: Size::default(),
162	        };
163	
164	        let mutable_state = WebWindowMutableState {
165	            renderer,
166	            bounds: initial_bounds,
167	            scale_factor: dpr,
168	            max_texture_dimension,
169	            title: String::new(),
170	            input_handler: None,
171	            is_fullscreen: false,
172	            is_active: true,
173	            is_hovered: false,
174	            mouse_position: Point::default(),
175	            modifiers: Modifiers::default(),
176	            capslock: Capslock::default(),
177	        };
178	
179	        let is_mac = is_mac_platform(&browser_window);
180	
181	        let inner = Rc::new(WebWindowInner {
182	            browser_window,
183	            canvas,
184	            input_element,
185	            has_device_pixel_support,
186	            is_mac,
187	            state: RefCell::new(mutable_state),
188	            callbacks: RefCell::new(WebWindowCallbacks::default()),
189	            click_state: RefCell::new(ClickState::default()),
190	            pressed_button: Cell::new(None),
191	            last_physical_size: Cell::new((0, 0)),
192	            notify_scale: Cell::new(false),
193	            is_composing: Cell::new(false),
194	            mql_handle: RefCell::new(None),
195	            pending_physical_size: Cell::new(None),
196	            raf_id: Cell::new(None),
197	            raf_function: RefCell::new(None),
198	        });
199	
200	        let raf_closure = inner.create_raf_closure();
201	        inner.wake_frame_loop();
202	
203	        let resize_observer_closure = Self::create_resize_observer_closure(Rc::clone(&inner));
204	        let resize_observer =
205	            web_sys::ResizeObserver::new(resize_observer_closure.as_ref().unchecked_ref()).ok();
206	
207	        if let Some(ref observer) = resize_observer {
208	            inner.observe_canvas(observer);
209	            inner.watch_dpr_changes(observer);
210	        }
211	
212	        let event_listeners = inner.register_event_listeners();
213	
214	        Ok(Self {
215	            inner,
216	            display,
217	            lifecycle,
218	            active_window,
219	            _raf_closure: raf_closure,
220	            _resize_observer: resize_observer,
221	            _resize_observer_closure: resize_observer_closure,
222	            _event_listeners: event_listeners,
223	        })
224	    }
225	
226	    fn create_resize_observer_closure(
227	        inner: Rc<WebWindowInner>,
228	    ) -> Closure<dyn FnMut(js_sys::Array)> {
229	        Closure::new(move |entries: js_sys::Array| {
230	            let entry: web_sys::ResizeObserverEntry = match entries.get(0).dyn_into().ok() {
231	                Some(entry) => entry,
232	                None => return,
233	            };
234	
235	            let dpr = inner.browser_window.device_pixel_ratio();
236	            let dpr_f32 = dpr as f32;
237	
238	            let (physical_width, physical_height, logical_width, logical_height) =
239	                if inner.has_device_pixel_support {
240	                    let size: web_sys::ResizeObserverSize = entry
241	                        .device_pixel_content_box_size()
242	                        .get(0)
243	                        .unchecked_into();
244	                    let pw = size.inline_size() as u32;
245	                    let ph = size.block_size() as u32;
246	                    let lw = pw as f64 / dpr;
247	                    let lh = ph as f64 / dpr;
248	                    (pw, ph, lw as f32, lh as f32)
249	                } else {
250	                    // Safari fallback: use contentRect (always CSS px).
251	                    let rect = entry.content_rect();
252	                    let lw = rect.width() as f32;
253	                    let lh = rect.height() as f32;
254	                    let pw = (lw as f64 * dpr).round() as u32;
255	                    let ph = (lh as f64 * dpr).round() as u32;
256	                    (pw, ph, lw, lh)
257	                };
258	
259	            let scale_changed = inner.notify_scale.replace(false);
260	            let prev = inner.last_physical_size.get();
261	            let size_changed = prev != (physical_width, physical_height);
262	
263	            if !scale_changed && !size_changed {
264	                return;
265	            }
266	            inner
267	                .last_physical_size
268	                .set((physical_width, physical_height));
269	
270	            // Skip rendering to a zero-size canvas (e.g. display:none).
271	            if physical_width == 0 || physical_height == 0 {
272	                {
273	                    let mut s = inner.state.borrow_mut();
274	                    s.bounds.size = Size::default();
275	                    s.scale_factor = dpr_f32;
276	                }
277	                // Still fire the callback so GPUI knows the window is gone.
278	                inner.with_callback(
279	                    |callbacks| &mut callbacks.resize,
280	                    |callback| callback(Size::default(), dpr_f32),
281	                );
282	                return;
283	            }
284	
285	            let max_texture_dimension = inner.state.borrow().max_texture_dimension;
286	            let clamped_width = physical_width.min(max_texture_dimension);
287	            let clamped_height = physical_height.min(max_texture_dimension);
288	
289	            // Recompute the logical size from the clamped physical size so
290	            // that scale_factor still maps GPUI's logical bounds exactly onto
291	            // the surface; otherwise clamping would silently distort the
292	            // effective scale.
293	            let (logical_width, logical_height) =
294	                if (clamped_width, clamped_height) != (physical_width, physical_height) {
295	                    (
296	                        (clamped_width as f64 / dpr) as f32,
297	                        (clamped_height as f64 / dpr) as f32,
298	                    )
299	                } else {
300	                    (logical_width, logical_height)
301	                };
302	
303	            inner
304	                .pending_physical_size
305	                .set(Some((clamped_width, clamped_height)));
306	
307	            {
308	                let mut s = inner.state.borrow_mut();
309	                s.bounds.size = Size {
310	                    width: px(logical_width),
311	                    height: px(logical_height),
312	                };
313	                s.scale_factor = dpr_f32;
314	            }
315	
316	            let new_size = Size {
317	                width: px(logical_width),
318	                height: px(logical_height),
319	            };
320	
321	            inner.with_callback(
322	                |callbacks| &mut callbacks.resize,
323	                |callback| callback(new_size, dpr_f32),
324	            );
325	        })
326	    }
327	}
