329	impl WebWindowInner {
330	    /// Invokes a registered callback with take/call/restore semantics.
331	    ///
332	    /// The callback is removed from the slot for the duration of the call, so
333	    /// the `RefCell` is not borrowed while user code runs: a callback that
334	    /// re-enters the platform window (dispatching input, registering
335	    /// handlers) would otherwise panic with a `BorrowMutError`. A re-entrant
336	    /// invocation of the same callback finds the slot empty and is a no-op.
337	    pub(crate) fn with_callback<C, R>(
338	        &self,
339	        select: impl Fn(&mut WebWindowCallbacks) -> &mut Option<C>,
340	        invoke: impl FnOnce(&mut C) -> R,
341	    ) -> Option<R> {
342	        let mut callback = select(&mut self.callbacks.borrow_mut()).take()?;
343	        let result = invoke(&mut callback);
344	        *select(&mut self.callbacks.borrow_mut()) = Some(callback);
345	        Some(result)
346	    }
347	
348	    fn create_raf_closure(self: &Rc<Self>) -> Closure<dyn FnMut()> {
349	        let this = Rc::clone(self);
350	        let closure = Closure::new(move || {
351	            // The request that fired is no longer pending; clear it before
352	            // running the frame so wakeups issued while the frame executes
353	            // (e.g. views invalidated during draw) schedule the next request
354	            // instead of being swallowed.
355	            this.raf_id.set(None);
356	            this.with_callback(
357	                |callbacks| &mut callbacks.request_frame,
358	                |callback| {
359	                    callback(RequestFrameOptions {
360	                        require_presentation: false,
361	                        force_render: false,
362	                    })
363	                },
364	            );
365	        });
366	
367	        let js_func: js_sys::Function =
368	            closure.as_ref().unchecked_ref::<js_sys::Function>().clone();
369	        *self.raf_function.borrow_mut() = Some(js_func);
370	
371	        closure
372	    }
373	
374	    pub(crate) fn wake_frame_loop(&self) {
375	        if self.raf_id.get().is_some() {
376	            return;
377	        }
378	        let raf_function = self.raf_function.borrow();
379	        if let Some(func) = raf_function.as_ref() {
380	            self.raf_id
381	                .set(self.browser_window.request_animation_frame(func).ok());
382	        }
383	    }
384	
385	    fn observe_canvas(&self, observer: &web_sys::ResizeObserver) {
386	        observer.unobserve(&self.canvas);
387	        if self.has_device_pixel_support {
388	            let options = web_sys::ResizeObserverOptions::new();
389	            options.set_box(web_sys::ResizeObserverBoxOptions::DevicePixelContentBox);
390	            observer.observe_with_options(&self.canvas, &options);
391	        } else {
392	            observer.observe(&self.canvas);
393	        }
394	    }
395	
396	    fn watch_dpr_changes(self: &Rc<Self>, observer: &web_sys::ResizeObserver) {
397	        let current_dpr = self.browser_window.device_pixel_ratio();
398	        let media_query =
399	            format!("(resolution: {current_dpr}dppx), (-webkit-device-pixel-ratio: {current_dpr})");
400	        let Some(mql) = self.browser_window.match_media(&media_query).ok().flatten() else {
401	            return;
402	        };
403	
404	        let this = Rc::clone(self);
405	        let observer = observer.clone();
406	
407	        let closure = Closure::<dyn FnMut(JsValue)>::new(move |_event: JsValue| {
408	            this.notify_scale.set(true);
409	            this.observe_canvas(&observer);
410	            this.watch_dpr_changes(&observer);
411	        });
412	
413	        mql.add_event_listener_with_callback("change", closure.as_ref().unchecked_ref())
414	            .ok();
415	
416	        *self.mql_handle.borrow_mut() = Some(MqlHandle {
417	            mql,
418	            _closure: closure,
419	        });
420	    }
421	
422	    pub(crate) fn register_visibility_change(self: &Rc<Self>) -> Option<EventListenerHandle> {
423	        let document = self.browser_window.document()?;
424	        let this = Rc::clone(self);
425	
426	        Some(EventListenerHandle::add(
427	            document.as_ref(),
428	            "visibilitychange",
429	            move |_event: JsValue| {
430	                let is_visible = this
431	                    .browser_window
432	                    .document()
433	                    .map(|doc| {
434	                        let state_str: String =
435	                            js_sys::Reflect::get(&doc, &"visibilityState".into())
436	                                .ok()
437	                                .and_then(|v| v.as_string())
438	                                .unwrap_or_default();
439	                        state_str == "visible"
440	                    })
441	                    .unwrap_or(true);
442	
443	                {
444	                    let mut state = this.state.borrow_mut();
445	                    state.is_active = is_visible;
446	                }
447	                this.with_callback(
448	                    |callbacks| &mut callbacks.active_status_change,
449	                    |callback| callback(is_visible),
450	                );
451	            },
452	        ))
453	    }
454	
455	    /// Tracks `fullscreenchange` instead of toggling a local flag: the user
456	    /// can exit fullscreen with Esc, and `requestFullscreen` can be rejected,
457	    /// so the document is the only reliable source of truth.
458	    pub(crate) fn register_fullscreen_change(self: &Rc<Self>) -> Option<EventListenerHandle> {
459	        let document = self.browser_window.document()?;
460	        let this = Rc::clone(self);
461	
462	        Some(EventListenerHandle::add(
463	            document.as_ref(),
464	            "fullscreenchange",
465	            move |_event: JsValue| {
466	                let is_fullscreen = this
467	                    .browser_window
468	                    .document()
469	                    .is_some_and(|document| document.fullscreen_element().is_some());
470	                this.state.borrow_mut().is_fullscreen = is_fullscreen;
471	            },
472	        ))
473	    }
474	
475	    pub(crate) fn with_input_handler<R>(
476	        &self,
477	        f: impl FnOnce(&mut PlatformInputHandler) -> R,
478	    ) -> Option<R> {
479	        let mut handler = self.state.borrow_mut().input_handler.take()?;
480	        let result = f(&mut handler);
481	        self.state.borrow_mut().input_handler = Some(handler);
482	        Some(result)
483	    }
484	
485	    pub(crate) fn register_appearance_change(self: &Rc<Self>) -> Option<EventListenerHandle> {
486	        let mql = self
487	            .browser_window
488	            .match_media("(prefers-color-scheme: dark)")
489	            .ok()??;
490	
491	        let this = Rc::clone(self);
492	        Some(EventListenerHandle::add(
493	            mql.as_ref(),
494	            "change",
495	            move |_event: JsValue| {
496	                this.with_callback(
497	                    |callbacks| &mut callbacks.appearance_changed,
498	                    |callback| callback(),
499	                );
500	            },
501	        ))
502	    }
503	}
