505	impl Drop for WebWindow {
506	    fn drop(&mut self) {
507	        // Cancel the pending requestAnimationFrame callback before
508	        // `_raf_closure` is freed, and disconnect the resize observer before
509	        // `_resize_observer_closure` is freed; a late invocation of either
510	        // would throw "closure invoked after being dropped".
511	        if let Some(raf_id) = self.inner.raf_id.take() {
512	            self.inner
513	                .browser_window
514	                .cancel_animation_frame(raf_id)
515	                .ok();
516	        }
517	        // A frame waker that outlives this window must not re-schedule the
518	        // freed closure; without a stored function, `wake_frame_loop` no-ops.
519	        self.inner.raf_function.borrow_mut().take();
520	        if let Some(ref observer) = self._resize_observer {
521	            observer.disconnect();
522	        }
523	
524	        // The DPR media-query closure captures an `Rc<WebWindowInner>` and is
525	        // stored inside the inner itself, forming a reference cycle; take it
526	        // out so the inner can actually be freed.
527	        self.inner.mql_handle.borrow_mut().take();
528	
529	        let canvas: &web_sys::Element = self.inner.canvas.as_ref();
530	        canvas.remove();
531	        let input_element: &web_sys::Element = self.inner.input_element.as_ref();
532	        input_element.remove();
533	        self.active_window.borrow_mut().take();
534	        self.lifecycle.set(WebWindowLifecycle::Closed);
535	    }
536	}
